import{_ as r,o,c as a,a2 as t}from"./chunks/framework.BTLSZHNB.js";const p=JSON.parse('{"title":"WorkerCronTrigger — takoform_worker_cron_trigger","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/worker-cron-trigger.md","filePath":"proposals/edge/worker-cron-trigger.md"}'),i={name:"proposals/edge/worker-cron-trigger.md"};function d(n,e,s,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="workercrontrigger-—-takoform-worker-cron-trigger" tabindex="-1">WorkerCronTrigger — <code>takoform_worker_cron_trigger</code> <a class="header-anchor" href="#workercrontrigger-—-takoform-worker-cron-trigger" aria-label="Permalink to &quot;WorkerCronTrigger — `takoform_worker_cron_trigger`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team runs periodic work — cache refresh, cleanup, digests — by having the platform invoke its worker&#39;s <code>scheduled</code> handler on a cron schedule.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. The trigger activates the worker from the outside; deleting the trigger never deletes the worker.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>cron</code> is the portable five-field cron subset, interpreted in UTC only. There is no timezone field, so two conforming hosts can never fire the same trigger at different instants. Each match invokes the scheduled handler of the worker&#39;s active deployment; a missed window is skipped, not queued.</p><p>The grammar is closed and deliberately small: exactly five single-value fields separated by single spaces, where minute is a literal <code>0</code>-<code>59</code>, hour a literal <code>0</code>-<code>23</code>, day-of-month <code>*</code> or <code>1</code>-<code>31</code>, month <code>*</code> or <code>1</code>-<code>12</code>, and day-of-week <code>*</code> or <code>0</code>-<code>6</code>. Ranges, lists, steps, and names are rejected, and <code>*</code> is not accepted in the minute or hour field: <code>* * * * *</code>, <code>0 * * * *</code>, and <code>*/5 * * * *</code> are all invalid. The most frequent representable schedule is therefore once per day at one fixed UTC time, and hourly or sub-hourly work cannot be declared with this Form. Widening the grammar changes the observable firing set, so it is a new definition version of this Form rather than a host-side relaxation; every conforming host must reject what this grammar rejects until then.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Schedule plus target is one observable fact. The UTC-only rule is the completeness boundary of decision 0008: leaving the zone open would let two hosts fire at observably different times.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Timezone-aware or calendar-aware scheduling (a <code>TimezoneSchedule</code>) carries different firing semantics and is separate family work.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Attaching a trigger to a worker whose versions do not declare the <code>scheduled</code> handler must fail closed. Updating <code>cron</code> is an in-place update; changing <code>worker</code> replaces the attachment.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The cron trigger of a proven edge platform, restricted to the interoperable five-field UTC subset already used by the retained catalog.</p>',20)])])}const f=r(i,[["render",d]]);export{p as __pageData,f as default};
